package textenc

import (
	"os"
	"testing"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/vk"
	"strix-halo-vulkan/zimage/qwen"
)

const strixHaloDeviceID = 0x1586

func newTestDevice(t *testing.T) (*vk.Device, func()) {
	t.Helper()
	inst, err := vk.NewInstance("qi21-textenc-test")
	if err != nil {
		t.Skipf("no Vulkan instance: %v", err)
	}
	devices, err := inst.PhysicalDevices()
	if err != nil || len(devices) == 0 {
		inst.Destroy()
		t.Skipf("no Vulkan devices: %v", err)
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
			break
		}
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		inst.Destroy()
		t.Skipf("no compute queue: %v", err)
	}
	sgs, err := phys.SubgroupSizeControl()
	if err != nil {
		inst.Destroy()
		t.Skipf("no subgroup size control query: %v", err)
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
		Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported,
	})
	if err != nil {
		inst.Destroy()
		t.Skipf("no device: %v", err)
	}
	t.Logf("device: %s", phys.Name)
	return dev, func() { dev.Destroy(); inst.Destroy() }
}

// The fp16 bounds are measured, and the story behind them matters (all
// numbers 2026-09-20, TestGPULadder and the torch probes beside it):
//
// This checkpoint's residual stream grows a ~13k massive-activation channel
// at layer 6 (and again at 16), carries it flat for 18 layers, and *cancels*
// it in layers 34-35 — the two layers Z-Image's hidden_states[-2] never ran,
// which is why zimage/qwen's fp16 path could hold 6e-3 and this one cannot.
// Every reduced-precision pass through the FFN injects ~5e-4 of bulk
// rounding variance into that channel (keeping just the spike elements exact
// measurably does NOT help), and when the channel collapses the carried
// error surfaces: rel 0.024 on a real prompt, 0.21 elementwise on the
// all-template empty prompt whose rows are mostly cancellation residue.
//
// Priced against the model's own deployment: the *official* bf16 pipeline
// deviates from fp32 by rel 2.0 (max abs 204) through the same mechanism —
// two orders of magnitude beyond this path. If Q3/Q6 ever show prompt
// adherence suffering, the known lever is an fp32-activation GEMM arm for
// the encoder, and at prompt-sized M (~40 rows) the encoder is
// weight-bandwidth-bound, so that arm would cost little; it is not built
// because nothing yet shows it is needed.
const (
	gpuTol      = 3e-2 // en/cjk: measured 0.024-0.027
	gpuEmptyTol = 0.25 // empty prompt: measured 0.214, residue-dominated
)

// TestGPUEncoder is Q1's GPU acceptance gate: zimage/qwen's GPUEncoder,
// unchanged, over the Qwen3-VL config — all 36 layers, no final norm — for
// the three dumped prompts. ~15 GB of fp16 banks, staged one layer at a
// time.
func TestGPUEncoder(t *testing.T) {
	if testing.Short() {
		t.Skip("stages 15 GB of fp16 banks")
	}
	m := loadManifest(t)
	if _, err := os.Stat(encoder); err != nil {
		t.Skipf("no text encoder checkpoint at %s", encoder)
	}
	cfg, err := LoadConfig(encoder)
	if err != nil {
		t.Fatal(err)
	}
	set, err := safetensors.OpenSet(encoder)
	if err != nil {
		t.Fatal(err)
	}
	defer set.Close()

	dev, done := newTestDevice(t)
	defer done()
	g, err := qwen.NewGPUEncoder(dev, set, cfg, cfg.NumLayers, 512, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()

	for _, label := range []string{"en", "cjk", "empty"} {
		p := m.Prompts[label]
		out, err := g.Forward(p.IDs)
		if err != nil {
			t.Fatal(err)
		}
		tol := gpuTol
		if label == "empty" {
			tol = gpuEmptyTol
		}
		if label == "en" {
			compareAt(t, "en_last_prenorm", out, loadRef(t, m, "en_last_prenorm"), tol)
		}
		embeds, err := Drop(out, m.DropIdx)
		if err != nil {
			t.Fatal(err)
		}
		compareAt(t, label+"_prompt_embeds", embeds, loadRef(t, m, label+"_prompt_embeds"), tol)
	}
}
// Measured 2026-09-26: 6.5e-5 (en), 2.4e-6 (cjk), 1.1e-4 (the 537-token
// README prompt), where the official bf16 pipeline is at 1.2–1.4e-2 against
// the same oracle. Unlike Qwen-Image's 8 B encoder (Q1: 0.024), nothing here
// cancels the massive-activation channel before layer 50 reads it.
const gpuTol = 5e-4

// q8Tol is the int8 bank's bound (VIDEO.md M11a). Measured 2026-09-26:
// 2.1e-4 (en), 1.7e-4 (cjk), 3.0e-4 (readme), 40x inside the official bf16
// pipeline's distance from the same oracle.
const q8Tol = 1e-3

// testBank is the bank H3_BANK names: fp16 (the default) or q8.
func testBank(t *testing.T) qwen.Bank {
	s := os.Getenv("H3_BANK")
	if s == "" {
		return qwen.BankFP16
	}
	b, err := qwen.ParseBank(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// TestGPUEncoder is M2's gate: zimage/qwen's GPU encoder, unchanged, over
// the 32 B config with Layers of its 64 layers, for every dumped prompt,
// against the fp32 oracle. It also reports where the official bf16 pipeline
// sits against the same oracle, which is the scale the bound is priced on.
// ~50 GB of fp16 banks.
func TestGPUEncoder(t *testing.T) {
	if testing.Short() {
		t.Skip("stages 50 GB of fp16 banks")
	}
	m := loadEncRef(t)
	if m.Layer != Layers {
		t.Fatalf("reference reads hidden_states[%d], this package %d", m.Layer, Layers)
	}
	cfg, err := LoadConfig(encoder)
	if err != nil {
		t.Skipf("no text encoder (%v)", err)
	}
	set, err := safetensors.OpenSet(encoder)
	if err != nil {
		t.Fatal(err)
	}
	defer set.Close()
	dev, done := newTestDevice(t)
	defer done()

	bank := testBank(t)
	start := time.Now()
	g, err := qwen.NewGPUEncoderBank(dev, set, cfg, Layers, 1024, nil, bank)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	t.Logf("staged %d layers (%s, %.1f GB) in %v", Layers, bank, float64(g.WeightBytes())/1e9, time.Since(start).Round(time.Millisecond))
	tol := gpuTol
	if bank == qwen.BankQ8 {
		tol = q8Tol
	}
	for _, label := range []string{"en", "cjk", "readme"} {
		start := time.Now()
		out, err := g.Forward(m.Prompts[label].IDs)
		if err != nil {
			t.Fatal(err)
		}
		took := time.Since(start)
		want := encMat(t, m, label+"_fp32")
		rel, maxAbs, rms := gap(out, want)
		brel, babs, _ := gap(encMat(t, m, label+"_bf16"), want)
		t.Logf("%-7s %4d tokens in %v: %s rel %.3g (max abs %.4g, rms %.3g); official bf16 rel %.3g (max abs %.4g)",
			label, out.Rows, took.Round(time.Millisecond), bank, rel, maxAbs, rms, brel, babs)
		if rel > tol || math.IsNaN(rel) {
			t.Errorf("%s: rel %.3g > %.0e", label, rel, tol)
		}
	}
}
package textenc

import (
	"fmt"
	"os"
	"testing"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/zimage/qwen"
)

// Q8.4's gate: the edit text encoding on the device.
//
// The conditions are the **dump's own** merged and deepstack rows rather than
// our tower's, for the same reason the CPU path's two-image case uses them —
// it makes this a gate on the text encoding instead of on the pair, and
// qimage/vision already gates the tower against the same dump. What is under
// test here is only what EncodeGPU adds to Q1's GPUEncoder: the host scatter
// before the upload, the uploaded mrope table, and the deepstack additions
// between the first three layers.
//
// The bound is gpuEditTol, measured here and not borrowed from Q1: an edit
// prompt lands at 0.059 (one image) and 0.064 (two) where the t2i prompts
// measure 0.024-0.027. That is twice the t2i number, and the reason it is a
// bound rather than a bug is TestGPUEditLadder, which walks the same run
// against the CPU port layer by layer and finds **Q1's mechanism, unchanged
// and in the same place**:
//
//	layers 0-5    rel ~1.1e-3, flat — the scatter, the mrope table and the
//	              deepstack injection are exact to fp16 rounding
//	layer 6       the massive-activation channel appears (rms 0.98 -> 21.1)
//	              and carries an absolute error of 4.46 *flat*
//	layer 16      a second jump (rms 26.0), the carried error 8.83, and it
//	              stays 8.83 and in the same column (270) for 18 layers —
//	              carried, not accumulated
//	layers 34-35  the channel cancels (rms 27.8 -> 20.0 -> 13.0) and the
//	              carried error surfaces: rel 0.0049 -> 0.0146 -> 0.0532
//
// So the last two layers produce the whole of the deviation, exactly as Q1
// described for t2i. And the *absolute* deviation does not move at all
// between the two paths: the worst element is **2.38 in all three cases** —
// the t2i "en" prompt, the one-image edit and the two-image edit, measured in
// the same hour. What the extra 2.4x buys is a different worst *relative*
// element (0.69 on an element of 11.8) under a lower rms floor (10.05 against
// en's 13), which is the metric moving rather than the error.
// Priced the same way Q1 priced its own: the
// *official* bf16 pipeline deviates from fp32 by rel 2.0 on this checkpoint,
// 30x further than this. The known lever, if an edit's prompt adherence ever
// looks wrong, is still the fp32-activation GEMM arm Q1 priced and did not
// build.
//
// edit_layer0_out is gated at layerTol instead, which is 4x its measurement
// rather than 90x: the shallow reading is what keeps a real mistake in the
// three new mechanisms from hiding under the fp16 bound.
const (
	gpuEditTol = 1e-1 // measured 0.059 (one image) / 0.064 (two)
	layerTol   = 5e-3 // layer 0 measured 1.1e-3
)

func TestGPUEditEncoder(t *testing.T) {
	if testing.Short() {
		t.Skip("stages 15 GB of fp16 banks")
	}
	m := loadEditManifest(t)
	if _, err := os.Stat(encoder); err != nil {
		t.Skipf("no text encoder checkpoint at %s", encoder)
	}
	cfg, err := LoadConfig(encoder)
	if err != nil {
		t.Fatal(err)
	}
	section, err := LoadMRope(encoder)
	if err != nil {
		t.Fatal(err)
	}
	set, err := safetensors.OpenSet(encoder)
	if err != nil {
		t.Fatal(err)
	}
	defer set.Close()

