package qwen

import (
	"fmt"
	"math"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/vk"
)

// Bank is how a model's projection weights are held on the device.
type Bank int

const (
	// BankFP16 is every projection in fp16 fragment tiles, read by the GEMMs
	// directly.
	BankFP16 Bank = iota
	// BankQ8 is every projection as int8 with one fp16 scale per 32 k of a
	// row (PackQ8), expanded into one fp16 scratch a layer at a time
	// (shaders/dit_dequant_q8.comp) just before that layer's GEMMs. Half
	// the memory, the same GEMMs, and ~1 ms a GB of weights on the device
	// (VIDEO.md M11a).
	BankQ8
)

func (b Bank) String() string {
	if b == BankQ8 {
		return "q8"
	}
	return "fp16"
}

// ParseBank reads "fp16" or "q8".
func ParseBank(s string) (Bank, error) {
	switch s {
	case "fp16":
		return BankFP16, nil
	case "q8", "int8":
		return BankQ8, nil
	}
	return 0, fmt.Errorf("qwen: bank %q; fp16 or q8", s)
}

// Q8Group is how many k of a row share one scale.
const Q8Group = 32

// Q8Bytes is how many bytes PackQ8 writes for an [n, k] weight: the int8
// tiles, then the scale plane, rounded up to 256 so the next matrix starts
// on a word and a tile.
func Q8Bytes(n, k int) int { return (n*k + n*k/Q8Group*2 + 255) &^ 255 }

// PackQ8 quantises a row-major [n, k] weight into dst (Q8Bytes(n, k) long):
// int8 in the fragment tiling -- tile (nt, kt) is 256 bytes holding (k, n)
// at (n%16)*16 + k%16, tiles kt-fastest -- then the fp16 scales, scale
// (nt, group, n%16) at (nt*k/32 + group)*16 + n%16. It is Kev's K7.1
// quantisation (kev.packQ8) and the LLM's L8 layout: q is rounded against
// the fp16 scale the expander multiplies by, amax/127 narrowed.
func PackQ8(dst []byte, w []float32, n, k int) error {
	if n%coopMatTile != 0 || k%64 != 0 {
		return fmt.Errorf("qwen: [%d %d] does not tile for the int8 bank", n, k)
	}
	if len(w) != n*k || len(dst) < Q8Bytes(n, k) {
		return fmt.Errorf("qwen: packing %d values into [%d %d] (%d bytes)", len(w), n, k, len(dst))
	}
	const tile = coopMatTile
	kt, kg := k/tile, k/Q8Group
	sc := dst[n*k:]
	parallelFor((n+packChunk-1)/packChunk, func(c int) {
		for r := c * packChunk; r < min((c+1)*packChunk, n); r++ {
			base := (r / tile) * kt * tile * tile
			lane := (r % tile) * tile
			sbase := (r/tile)*kg*tile + r%tile
			x := w[r*k : (r+1)*k]
			for gi := 0; gi < kg; gi++ {
				blk := x[gi*Q8Group : (gi+1)*Q8Group]
				var amax float32
				for _, v := range blk {
					amax = max(amax, float32(math.Abs(float64(v))))
				}
				dh := safetensors.F32ToF16(amax / 127)
	ropeAdjacent bool
	// noCausal uses the grouped-query build without the causal mask, i.e.
	// lets every token see the whole prompt.
	noCausal bool
	// qkNormWide norms q and k over the full width instead of per head.
	qkNormWide bool
	// wrongBLayout stages every weight row-major while the kernel reads
	// fragment tiles.
	wrongBLayout bool
	// shiftBank sends every layer's projections to the next bank at the same
	// offsets, so layer i reads layer i+1's weights -- the mistake a
	// per-bank descriptor set invites, and one that produces a perfectly
	// plausible tensor.
	shiftBank bool
}

// layerWeights is where one layer's weights sit in the arenas.
type layerWeights struct {
	// fp32 arena: the four norms.
	attnNorm, ffnNorm uint32
	qNorm, kNorm      uint32
	// fp16 bank and the offset of each projection inside it, in halves.
	// Under BankQ8 that is the shared scratch, the same for every layer.
	bank int
	bOff map[Proj]uint32
	// BankQ8: the int8 bank and each projection's byte offset in it.
	qbank int
	qOff  map[Proj]uint32
}

// GPUEncoder runs Qwen3 layers on the device. One instance holds every layer
// the pipeline needs -- 7.06 GB across two storage buffers -- so a prompt is
// a dispatch sequence and not a load.
type GPUEncoder struct {
	dev *vk.Device
	cfg *Config

	wbuf  *vk.Buffer
	abuf  *vk.Buffer
	hbuf  *vk.Buffer
	banks []*vk.Buffer
	// bank is how the projections are held. Under BankQ8, qbanks hold them
	// as int8 and banks is the one fp16 scratch a layer is expanded into
	// by its first seven dispatches (dequant, one pipeline per qbank).
	bank    Bank
	qbanks  []*vk.Buffer
	dequant []*vk.ComputePipeline

	pipes map[string]*vk.ComputePipeline
	gemms []map[GEMMKernel]*vk.ComputePipeline
	mods  []*vk.ShaderModule

	// AutoPlan re-plans every run for its own length, using PlanFor. It is on
	// by default and it is free: every rung reads the same staged weight, so
	// this changes which pipeline a dispatch names and nothing else. Set it
	// false to hold a plan across lengths, which is what the ladder does.
	AutoPlan bool

	plan    GEMMPlan
	kernels map[GEMMKernel]gemmVariant
	attn    attnVariant
	perLayerQ := 0
	for _, r := range projOrder {
		perLayerQ += Q8Bytes(shapes[r][0], shapes[r][1])
	}

	g.w = make([]layerWeights, layers)
	var bankElems, qbankBytes []int
	cur := -1
	for i := range g.w {
		w := layerWeights{bOff: make(map[Proj]uint32, len(projOrder))}
		w.attnNorm = uint32(total32)
		w.ffnNorm = w.attnNorm + uint32(c.HiddenSize)
		w.qNorm = w.ffnNorm + uint32(c.HiddenSize)
		w.kNorm = w.qNorm + uint32(c.HeadDim)
		total32 += perLayer32

		if g.bank == BankQ8 {
			// Every layer is expanded into the same scratch, so its fp16
			// offsets are the first layer's.
			if i == 0 {
				bankElems = []int{0}
				for _, r := range projOrder {
					w.bOff[r] = uint32(bankElems[0])
					bankElems[0] += bElems(shapes[r][0], shapes[r][1], kernelLayout)
				}
			} else {
				w.bOff = g.w[0].bOff
			}
			if len(qbankBytes) == 0 || qbankBytes[len(qbankBytes)-1]+perLayerQ > bankBytes {
				qbankBytes = append(qbankBytes, 0)
			}
			w.qbank = len(qbankBytes) - 1
			w.qOff = make(map[Proj]uint32, len(projOrder))
			for _, r := range projOrder {
				w.qOff[r] = uint32(qbankBytes[w.qbank])
				qbankBytes[w.qbank] += Q8Bytes(shapes[r][0], shapes[r][1])
			}
			g.w[i] = w
			continue
		}
		if cur < 0 || (bankElems[cur]+perLayer16)*2 > bankBytes {
		g.wbuf.WriteFloat32At(int(w.qNorm), layer.QNorm.Weight)
		g.wbuf.WriteFloat32At(int(w.kNorm), layer.KNorm.Weight)

		lins := map[Proj]*Linear{
			ProjQ: layer.Q, ProjK: layer.K, ProjV: layer.V, ProjO: layer.O,
			ProjGate: layer.Gate, ProjUp: layer.Up, ProjDown: layer.Down,
		}
		bank := g.banks[w.bank]
		for _, r := range projOrder {
			lin := lins[r]
			if lin.Out != shapes[r][0] || lin.In != shapes[r][1] {
				return fmt.Errorf("qwen: layer %d %s is [%d %d], want %v", i, r, lin.Out, lin.In, shapes[r])
			}
			if g.bank == BankQ8 {
				buf := make([]byte, Q8Bytes(lin.Out, lin.In))
				if err := PackQ8(buf, lin.Weight, lin.Out, lin.In); err != nil {
					return err
				}
				g.qbanks[w.qbank].WriteBytesAt(int(w.qOff[r]), buf)
				continue
			}
			buf := make([]uint16, bElems(lin.Out, lin.In, g.stagedLayout))
			packB(buf, lin.Weight, lin.Out, lin.In, g.stagedLayout)
			bank.WriteUint16At(int(w.bOff[r]), buf)
		}
	}
	return nil
}

// packChunk is how many output rows one worker narrows at a time.
const packChunk = 64
	// switched off and this is x += y.
	residual := func(kind string, y uint32) {
		pc := base
		pc.InOff, pc.OutOff = y, g.aX
		add("add", kind, uint32(g.rows), 1, pc)
	}

	// ---- The int8 bank's expansion into the scratch every GEMM below reads.
	if g.bank == BankQ8 {
		shapes := g.projShapes()
		for _, r := range projOrder {
			d = append(d, Q8Dispatch(g.dequant[w.qbank], w.qOff[r], w.bOff[r], shapes[r][0], shapes[r][1]))
			kinds = append(kinds, "dequant "+string(r))
		}
	}

	// ---- Attention.
	const log2e = 1.4426950408889634
	scale := float32(1/math.Sqrt(float64(c.HeadDim))) * log2e
	normF16("attn in", g.aX, g.hA, w.attnNorm, c.HiddenSize, g.ldaDim)
	for _, s := range []struct {
		r    Proj
		kind string
		out  uint32
		n    int
	}{{ProjQ, "gemm q", g.aQ, qWidth}, {ProjK, "gemm k", g.aK, kvWidth}, {ProjV, "gemm v", g.aV, kvWidth}} {

