			ProjGate: layer.Gate, ProjUp: layer.Up, ProjDown: layer.Down,
		}
		bank := g.banks[w.bank]
		for _, r := range projOrder {
			lin := lins[r]
			if lin.Out != shapes[r][0] || lin.In != shapes[r][1] {
				return fmt.Errorf("qwen: layer %d %s is [%d %d], want %v", i, r, lin.Out, lin.In, shapes[r])
