// testBank is the bank QIMAGE_BANK names: fp16 (the default) or q8.
func testBank(t *testing.T) qwen.Bank {
	t.Helper()
	s := os.Getenv("QIMAGE_BANK")
	if s == "" {
		return qwen.BankFP16
	}
	b, err := qwen.ParseBank(s)
	if err != nil {
