// imageDistance is the oracle comparison in the reference's own [0, 1]
// space, the same instrument TestEndToEndImage uses.
func imageDistance(got *qvae.Tensor, want *qwen.Mat) (maxAbs, mean float64) {
	var sumAbs float64
	for h := 0; h < got.H; h++ {
		for w := 0; w < got.W; w++ {
